#include <stdio.h>

int main(void) {
    int n, i;
    int sum = 0;
    int factor;
    scanf("%d %d", &n, &factor);
    for (i = 0; i < n; i++) {
        int v;
        scanf("%d", &v);
        sum += v;
    }
    sum *= factor;
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>

