    int income;
    scanf("%d", &income);
    double tax = (income <= 10000) ? 0.0
               : (income <= 50000) ? (income - 10000) * 0.10
               : (income <= 100000) ? (4000 + (income - 50000) * 0.20)
               : (14000 + (income - 100000) * 0.30);
    printf("%.2f\n", tax);
    return 0;
}

